import{_ as p,C as i,o as l,c as t,ag as s,E as e}from"./chunks/framework.DUTPmUpA.js";const r="/_assets/y2BUNcS.oA55nttY.png",c="/_assets/g2nWY-22554172f6.kc48TXBa.png",o="/_assets/g2o1O-b46e113293.Fa9XSFkB.png",d="/_assets/g2jo2-6c85128308.Dl17qkaD.png",b="/_assets/g3HVp-27ef775669.CANEnG9R.png",u="data:image/png;base64,",m="/_assets/DigitalDefinitiveChimpanzee.DQlPx4gg.mp4",h="/_assets/SkeletalIcyDalmatian.D881i-WS.mp4",g="/_assets/g2zNP-d1e018010e.Caa-zW0C.png",v="/_assets/g2yTG-93f1641866.B7A5s3bw.png",E=JSON.parse('{"title":"Введение в создание сценариев","description":"","frontmatter":{"title":"Введение в создание сценариев","author":"Noya","steamId":"76561198046984233","date":"18.02.2015"},"headers":[],"relativePath":"scripting-introduction.md","filePath":"scripting-introduction.md"}'),A={name:"scripting-introduction.md"};function f(_,n,T,k,y,N){const a=i("StaticVideo");return l(),t("div",null,[n[0]||(n[0]=s(`<p>ение в создание сценариев</p><p>Это руководство, часть 2 <a href="./getting-started">Getting Started With Dota 2 Modding</a>, предназначено для объяснения основ программирования пользовательских модов Dota 2.</p><h2 id="скрипты" tabindex="-1">Скрипты <a class="header-anchor" href="#скрипты" aria-label="Permalink to &quot;Скрипты&quot;">​</a></h2><p>Итак, теперь, когда у вас запущен только что созданный игровой режим и вы немного поигрались с редактором карт, пришло время перейти к программированию пользовательских карт Dota 2.</p><p>Зайдите в папку &lt;addonName&gt;/scripts/. Две основные папки сценариев — <code>npc</code> и <code>vscripts</code>. Первая содержит следующие файлы <code>.txt</code>:</p><ul><li><code>npc_abilities_custom.txt</code> - Содержит все пользовательские возможности игрового режима.</li><li><code>npc_heroes_custom.txt</code> — Герои со своими способностями и характеристиками.</li><li><code>npc_items_custom.txt</code> - Предметы - это способности, которые входят в инвентарь юнитов.</li><li><code>npc_units_custom.txt</code> - Все данные для юнитов, не являющихся героями, таких как здания или существа.</li><li><code>npc_abilities_override.txt</code> - Модифицированные способности/предметы доты с измененными значениями.</li><li><code>herolist.txt</code> - Список героев, доступных для выбора.</li></ul><p>Эти файлы определяются с помощью KeyValues ​​(KV) и являются ядром <strong>системы DataDriven</strong>. Хотя они соответствуют определению языка программирования, они больше похожи на большую таблицу, содержащую все возможные данные в статическом документе. Он использует относительно простой синтаксис, единственными специальными символами которого являются фигурные скобки и кавычки, с чередующимися наборами пар «Ключ» и «Значение» или «Ключ» <code>{table}</code>, где <code>table</code> — еще один набор KeyValues.</p><p>KV будет определять данные способностей/предметов/юнитов, а более детальное поведение обрабатывается с помощью Lua или TypeScript.</p><p>Каждый файл .txt содержит свои конкретные KV, и при запуске игры каждый клиент (и сервер) будет их интерпретировать. Изменения в этих файлах не вступят в силу, пока игра не будет запущена снова, поэтому внимательно следите за синтаксисом, поскольку любые дополнительные/отсутствующие <code>&quot;</code> или <code>{</code> <code>}</code> обычно делают все значения ключей, которые появляются после этой ошибки, непригодными для использования. Последовательный <a href="https://en.wikipedia.org/wiki/Indent_style" target="_blank" rel="noreferrer">indentation</a> — хорошая практика для раннего обучения! KV чувствителен к регистру, поэтому обратите внимание на то, чтобы писать все так, как того требует игра. Если ваш КВ не работает, попробуйте поместить его в <a href="https://arhowk.github.io/" target="_blank" rel="noreferrer">the KV checker</a> для поиска ошибок. Теперь самое время подготовить вашу среду для написания скриптов Dota. Для этого лучше всего получить <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a>. Используйте VSCode, чтобы открыть корневой каталог аддона, выбрав «Файл» &gt; «Открыть папку…».</p><h2 id="запуск-и-тестирование-вашеи-игры" tabindex="-1">Запуск и тестирование вашей игры <a class="header-anchor" href="#запуск-и-тестирование-вашеи-игры" aria-label="Permalink to &quot;Запуск и тестирование вашей игры&quot;">​</a></h2><p>После того, как ваша среда настроена, вы можете попробовать запустить дополнение. Откройте инструменты мастерской (если вы не можете их найти, они находятся в <code>/Steam/steamapps/common/dota 2 beta/game/bin/win64/dota2cfg.exe</code>, добавьте это в закладки) и выберите свой аддон.</p><p>После запуска браузера ресурсов откройте консоль с помощью кнопок вверху. Чтобы запустить аддон, просто введите следующую команду в нижней части консоли:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dota_launch_custom_game &lt;custom_game_name&gt; &lt;map_name&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Если вы этого не сделали, вам сначала нужно будет создать карту с помощью Hammer, прежде чем вы сможете запустить на ней игру. Вы также можете запустить игру на карте Dota 2 по умолчанию, используя:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dota_launch_custom_game &lt;custom_game_name&gt; dota</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>После этой команды вы войдете в игру по правилам вашего аддона. Если вы хотите перезапустить игру, чтобы перезагрузить скрипты, просто повторите команду запуска (нажав стрелку вверх в консоли) или набрав <code>restart</code> в консоли.</p><h2 id="сценарии-lua-typescript" tabindex="-1">Сценарии Lua/TypeScript <a class="header-anchor" href="#сценарии-lua-typescript" aria-label="Permalink to &quot;Сценарии Lua/TypeScript&quot;">​</a></h2><p>Возвращаясь к папке game/scripts, мы видим папку <code>vscripts</code>. Здесь размещаются все скрипты Lua/TypeScript.</p><h3 id="игровая-логика" tabindex="-1">Игровая логика <a class="header-anchor" href="#игровая-логика" aria-label="Permalink to &quot;Игровая логика&quot;">​</a></h3><p>В каждом игровом режиме должен присутствовать файл с именем <code>addon_game_mode.lua</code>. Хотя в этот файл можно добавить игровую логику (и, по сути, Valve так и сделала в своем тестовом примере), рекомендуется зарезервировать этот файл только для этих двух функций:</p><ul><li><code>Precache</code>, когда игра запускается и игроки выбирают своих героев, движок попытается загрузить соответствующие модели/частицы/звуки этим героям. Если мы динамически используем ресурс в Lua перед предварительной загрузкой, он не будет отображаться должным образом.</li><li><code>Activate</code>, создает объект основного игрового режима и вызывает функцию инициализации.</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>--[[</span></span>
<span class="line"><span>    Basic Barebones</span></span>
<span class="line"><span>]]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- Required files to be visible from anywhere</span></span>
<span class="line"><span>require( &#39;timers&#39; )</span></span>
<span class="line"><span>require( &#39;barebones&#39; )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function Precache( context )</span></span>
<span class="line"><span>    -- Precache things here</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- Create the game mode when we activate</span></span>
<span class="line"><span>function Activate()</span></span>
<span class="line"><span>    GameRules.GameMode = GameMode()</span></span>
<span class="line"><span>    GameRules.GameMode:InitGameMode()</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>Используя наши barebone-системы, вам не нужно трогать этот файл, за исключением очень специфических ситуаций, и вся основная игровая логика будет закодирована в <code>gamemode.lua</code> (для более старых версий это <code>barebones.lua</code>), что уже требовалось. С этого момента мы будем называть его вашим <em>основным lua-файлом</em>.</p><p>После завершения <code>addon_game_mode</code> <code>Precache</code> и <code>Activate</code> первой функцией, которая будет выполнена в файле <code>barebones.lua</code>, будет <code>GameMode:InitGameMode()</code>.</p><p>Здесь игра начинается с инициализации всевозможных правил и функций, которые регистрируются в объектах GameRules и GameMode. Для этого в файле <code>settings.lua</code> определено множество переменных, которые помогают организовать такие параметры, как настройки золота, убийства, пользовательские уровни и т. д.</p><p>Это синтаксис функции, применяемой к GameRules, с одним логическим параметром:</p><p><code>GameRules:SetHeroRespawnEnabled( ENABLE_HERO_RESPAWN )</code> Как и KV, Lua чувствителен к регистру. Кроме того, размещение функций в вашем основном файле Lua обычно не имеет значения. Все строки сценария внутри вызова функции будут выполняться одна за другой, возможно, в одном и том же <em>frame</em>; один кадр в Доте составляет 1/30 секунды.</p><p>Обратите внимание на использование двоеточия <code>:</code> перед функцией. В Lua мы получаем доступ к различным <strong>функциям Game API</strong>. Мы говорим, что <code>GameRules</code> — это <strong>HScript</strong> или <strong>дескриптор</strong>. Дескрипторы — это, по сути, огромные таблицы со всей необходимой информацией об объекте. В <a href="https://moddota.com/api/#!/vscripts" target="_blank" rel="noreferrer">Scripting API page</a> вы увидите множество различных типов функций, которые могут использовать разные дескрипторы.</p><p>Глобальным функциям не нужен префикс дескриптора <code>:</code>. Герои, существа, способности и предметы имеют разные классы дескрипторов, и попытка вызвать функцию через несовместимый класс приведет к ошибке VScript, в виде розового текста в консоли и красного текста на игровом экране.</p><h3 id="консоль" tabindex="-1">Консоль <a class="header-anchor" href="#консоль" aria-label="Permalink to &quot;Консоль&quot;">​</a></h3><p>Вы можете получить доступ к игровой консоли, нажав клавишу \`.</p><p>Это предоставит массу полезной информации для отладки. Различные цвета представляют различные «каналы» информации. По умолчанию все каналы находятся в одной вкладке «Журнал: по умолчанию». Настоятельно рекомендуется создать свои собственные вкладки, чтобы разделить средство просмотра журналов. <img src="`+r+'" alt="img"></p><p>Для сценариев Lua нам нужна вкладка VScript. Сообщения о системе DataDriven находятся в общем канале желтым цветом вместе с некоторой другой информацией, для этого тоже сделайте отдельный просмотрщик.</p><p><img src="'+c+'" alt="img"></p><p>Новые вкладки:</p><p><img src="'+o+'" alt="img"></p><p>Консоль будет уведомлять всякий раз, когда происходит ошибка сценария Lua, либо при загрузке игры (ошибка компиляции синтаксиса), либо во время выполнения. В этой ошибке я написал GameRules.SetHeroRespawnEnabled с <code>.</code> вместо <code>:</code>. <img src="'+d+'" alt="img"></p><p>Затем вы можете отследить ошибку до этой строки и попытаться ее устранить, написав <strong>script_reload</strong> в консоли, чтобы перезагрузить скрипт и проверить, действительно ли он был исправлен.</p><p>Синтаксическая ошибка DataDriven обычно выглядит следующим образом:</p><p><img src="'+b+`" alt="img"></p><h3 id="события-движка" tabindex="-1">События движка <a class="header-anchor" href="#события-движка" aria-label="Permalink to &quot;События движка&quot;">​</a></h3><p>Второй сегмент функции InitGameMode — это <strong>Слушатели</strong>: <code>ListenToGameEvent(&#39;dota_player_gained_level&#39;, Dynamic_Wrap(GameMode, &#39;OnPlayerLevelUp&#39;), self)</code></p><p>Структура этого ListenToGameEvent читается так:</p><p><strong>Каждый раз, когда срабатывает событие dota_player_gained_level, выполняйте сценарии внутри функции OnPlayerLevelUp.</strong></p><p><code>OnPlayerLevelUp</code> и <code>GameMode</code> (или <code>barebones</code> в обновленной версии) — это просто имена функции и имени основного класса, которые мы придумали, обычно вам не нужно о них беспокоиться, все прослушиватели и функции уже доступны в базовой версии и готовы к расширению. <code>Dynamic_Wrap</code> — это функция, гарантирующая, что команда <code>script_reload</code> также перезагружает прослушиватели. <code>script_reload</code> перезапускает сценарии Lua во время выполнения, в отличие от файлов DataDriven, которые требуют полного перезапуска игры. Как вы можете видеть на примере barebone-системы, существует множество возможных событий, и не все из них там перечислены, это только наиболее используемые.</p><p>Третья и последняя часть <code>InitGameMode</code> в упрощенных Barebone-системах — это самостоятельно определяемые переменные для отслеживания информации. Они используют объект <code>self.</code>, который является локальной ссылкой на объект GameMode, видимый через все функции внутри основного файла lua. Добавление информации к такой сущности, как <code>entity.</code>, широко называется «индексированием» и по сути представляет собой добавление еще одной записи в большую таблицу этой сущности. Это очень полезно, поскольку эта информация хранится под дескриптором сущности, видимым повсюду, и не изменится, пока мы не переназначим ее или не уничтожим.</p><p>Хватит теории, давайте посмотрим, как все это устроено. Давайте взглянем на функцию OnNPCSpawned, которая является прослушивателем <code>npc_spawned</code> и срабатывает каждый раз, когда на карту добавляется объект юнита или героя. Давайте проанализируем содержимое функции по умолчанию <code>OnNPCSpawned</code>:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>-- An NPC has spawned somewhere in game.  This includes heroes</span></span>
<span class="line"><span>function GameMode:OnNPCSpawned(keys)</span></span>
<span class="line"><span>    print(&quot;[BAREBONES] NPC Spawned&quot;)</span></span>
<span class="line"><span>    DeepPrintTable(keys)</span></span>
<span class="line"><span>    local npc = EntIndexToHScript(keys.entindex)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if npc:IsRealHero() and npc.bFirstSpawned == nil then</span></span>
<span class="line"><span>        npc.bFirstSpawned = true</span></span>
<span class="line"><span>        GameMode:OnHeroInGame(npc)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>// An NPC has spawned somewhere in game.  This includes heroes</span></span>
<span class="line"><span>public OnNPCSpawned(event: NpcSpawnedEvent) {</span></span>
<span class="line"><span>    print(&quot;[BAREBONES] NPC Spawned&quot;);</span></span>
<span class="line"><span>    DeepPrintTable(event);</span></span>
<span class="line"><span>    const npc = EntIndexToHScript(event.entindex);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (npc.IsRealHero() &amp;&amp; npc.bFirstSpawned == undefined) {</span></span>
<span class="line"><span>        npc.bFirstSpawned = true;</span></span>
<span class="line"><span>        OnHeroInGame(npc);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>:::</p><p>First line will print the string in the VConsole. The print function is native to Lua, and accepts multiple parameters separated by commas.</p><p><code>DeepPrintTable</code> is a Global Valve-made function which will display the information of the table passed. For keys in this case, it will be the .entindex and .splitscreenplayer. The <strong>entity index</strong> is a very important number to reference the entity. Ignore splitscreenplayer, it&#39;s just legacy source stuff and never used in Dota 2.</p><p><img src="`+u+`" alt="img"></p><p>The next line defines a local variable. In Lua local variables have their scope limited to the block where they are declared. It is good programming style to use local variables whenever possible. Local variables help you avoid cluttering the global environment with unnecessary names. Moreover, access to local variables is faster than to global ones.</p><p><code>local npc = EntIndexToHScript(keys.entindex)</code></p><p>По сути, это чтение информации, предоставленной событием, и сохранение ее в локальной переменной внутри этого вызова функции. В этом примере все прослушиватели и их функции уже обработаны, но для справки вы всегда можете проверить <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Scripting/Built-In_Engine_Events" target="_blank" rel="noreferrer">Built-In_Engine_Events wiki page</a>, чтобы точно знать, какие параметры передаются каждым событием.</p><p>Локальная переменная npc — это HScript типа дескриптора. Все изменения, внесенные в переменную npc, отразятся на созданном юните.</p><p>Следующая строка является условной: сначала она проверяет, является ли NPC настоящим героем (это исключает иллюзии), а также проверяет, не присвоен ли еще индекс .bFirstSpawned (самоопределяемая переменная). Если оба условия истинны, изменяет логическое значение на true и вызывает функцию OnHeroInGame.</p><p>Чтобы закончить это базовое руководство по Dota Lua, давайте изменим функцию OnNPCSpawned так, чтобы при появлении юнита с именем npc_dota_neutral_kobold подождал 1 секунду, а затем уничтожил себя. К первому оператору if добавлено условие else-if:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>function GameMode:OnNPCSpawned(keys)</span></span>
<span class="line"><span>    local npc = EntIndexToHScript(keys.entindex)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if npc:IsRealHero() and npc.bFirstSpawned == nil then</span></span>
<span class="line"><span>        npc.bFirstSpawned = true</span></span>
<span class="line"><span>        GameMode:OnHeroInGame(npc)</span></span>
<span class="line"><span>    elseif npc:GetUnitName() == &quot;npc_dota_neutral_kobold&quot; then</span></span>
<span class="line"><span>        Timers:CreateTimer( 1.0 , function()</span></span>
<span class="line"><span>            npc:ForceKill(true)</span></span>
<span class="line"><span>        end)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>public OnNPCSpawned(event: NpcSpawnedEvent) {</span></span>
<span class="line"><span>    const npc = EntIndexToHScript(keys.entindex);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (npc.IsRealHero() &amp;&amp; npc.bFirstSpawned == undefined) {</span></span>
<span class="line"><span>        npc.bFirstSpawned = true;</span></span>
<span class="line"><span>        OnHeroInGame(npc);</span></span>
<span class="line"><span>    } else if (npc.GetUnitName() == &quot;npc_dota_neutral_kobold&quot;) {</span></span>
<span class="line"><span>        Timers.CreateTimer(1.0, () =&gt; {</span></span>
<span class="line"><span>            npc.ForceKill(true);</span></span>
<span class="line"><span>        });</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>:::</p><p>Here we make use of the Timers library for a simple 1.0 second delay, there are many different timer functions included and explained in <code>timers.lua</code>. The bool on ForceKill is to enable the death animation.</p>`,65)),e(a,{path:m}),n[1]||(n[1]=s(`<h3 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h3><p>Tables are the most important structure we will have to use. As mentioned before, all the info on entities can be seen as a table (even though it&#39;s technically a pointer to a C++ object), and you Get and Set the values through the various Game API functions.</p><p>В API есть несколько функций, которые возвращают таблицу дескрипторов объектов.</p><p>Допустим, вы хотите найти все юниты рядом с появившимся кобольдом и убить их. Для этой цели можно использовать функцию <code>FindUnitsInRadius</code>, которая принимает множество параметров разных типов, что стоит объяснить:</p><p><code>table FindUnitsInRadius(int teamNumber, Vector position, handle cacheUnit, float radius, int teamFilter, int typeFilter, int flagFilter, int order, bool canGrowCache)</code></p><p>Параметры должны быть именно в этом порядке. Эта функция является глобальной, поэтому <code>handle:</code> не требуется, но нам нужно сохранить таблицу в переменной, например:</p><p><code>local units = FindUnitsInRadius(...)</code></p><p>Для команды TeamNumber узнать, в какой команде находится объект, можно с помощью <code>GetTeamNumber()</code> в дескрипторе NPC. Что касается других параметров фильтра, то вместо целых чисел мы используем группу <strong>Констант</strong>, которые представляют различные числовые значения. Полный список констант — <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Scripting/Constants" target="_blank" rel="noreferrer">found on this wiki page</a>. Вектор представлен как координаты Vector(x,y,z). Функция получения положения конкретного юнита называется <code>GetAbsOrigin</code> и принимает дескриптор NPC.</p><p>Что касается параметров кэша, просто оставьте их равными нулю и false, в целом они бесполезны.</p><p>Полный вызов функции для получения героев в радиусе 500 от порожденного кобольда будет:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>local units = FindUnitsInRadius(npc:GetTeamNumber(), npc:GetAbsOrigin(), nil, 500,</span></span>
<span class="line"><span>                                DOTA_UNIT_TARGET_TEAM_ENEMY, bit.bor(DOTA_UNIT_TARGET_BASIC, DOTA_UNIT_TARGET_HERO),</span></span>
<span class="line"><span>                                DOTA_UNIT_TARGET_FLAG_NONE, FIND_ANY_ORDER, false)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>const units = FindUnitsInRadius(</span></span>
<span class="line"><span>  npc.GetTeamNumber(),</span></span>
<span class="line"><span>  npc.GetAbsOrigin(),</span></span>
<span class="line"><span>  undefined,</span></span>
<span class="line"><span>  500,</span></span>
<span class="line"><span>  UnitTargetTeam.ENEMY,</span></span>
<span class="line"><span>  UnitTargetType.Basic | UnitTargetType.HERO,</span></span>
<span class="line"><span>  UnitTargetFlags.NONE,</span></span>
<span class="line"><span>  FindOrder.FIND_ANY_ORDER,</span></span>
<span class="line"><span>  false,</span></span>
<span class="line"><span>);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>:::</p><p>The use of extra break lines is just to make it more readable. Now we want to <strong>iterate over the entities of this table</strong>, which is done like this:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-GexNG" id="tab-IuzeAYm" checked><label data-title="txt" for="tab-IuzeAYm">txt</label><input type="radio" name="group-GexNG" id="tab-sArxShD"><label data-title="txt" for="tab-sArxShD">txt</label></div><div class="blocks"><div class="language- vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>for key, unit in pairs(units) do</span></span>
<span class="line"><span>    print(key, value)</span></span>
<span class="line"><span>    unit:ForceKill(true)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>for (const unit of units) {</span></span>
<span class="line"><span>  unit.ForceKill(true);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></div></div><p>The <code>key</code> and <code>unit</code> are the chosen names to refer to the position and value inside the <em>units</em> table, which will be read in pairs. Using <code>_</code> as the name of the key is a good convention when you want to make it clear that the first parameter won&#39;t be used. The 2nd parameter, unit, is used to iterate handles of the units found.</p><p>There is one more thing to consider: the &quot;wait one frame&quot; issue. Because all units are actually spawned at the (0,0,0) coordinates and then moved to the desired position, many times you&#39;ll need to create a 0 second timer (executes next frame) for some scripts to work, and this is one of those cases.</p><p>So, <code>OnNPCSpawned</code> is looking like this:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-2i7dP" id="tab-nqFt0A3" checked><label data-title="txt" for="tab-nqFt0A3">txt</label><input type="radio" name="group-2i7dP" id="tab-21F-iTL"><label data-title="txt" for="tab-21F-iTL">txt</label></div><div class="blocks"><div class="language- vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>function GameMode:OnNPCSpawned(keys)</span></span>
<span class="line"><span>    local npc = EntIndexToHScript(keys.entindex)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if npc:IsRealHero() and npc.bFirstSpawned == nil then</span></span>
<span class="line"><span>        npc.bFirstSpawned = true</span></span>
<span class="line"><span>        GameMode:OnHeroInGame(npc)</span></span>
<span class="line"><span>    elseif npc:GetUnitName() == &quot;npc_dota_neutral_kobold&quot; then</span></span>
<span class="line"><span>        Timers:CreateTimer(0, function()</span></span>
<span class="line"><span>            local units = FindUnitsInRadius(npc:GetTeamNumber(), npc:GetAbsOrigin(), nil, 500,</span></span>
<span class="line"><span>                                            DOTA_UNIT_TARGET_TEAM_ENEMY, DOTA_UNIT_TARGET_HERO,</span></span>
<span class="line"><span>                                            DOTA_UNIT_TARGET_FLAG_NONE, FIND_ANY_ORDER, false)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            for key, value in pairs(units) do</span></span>
<span class="line"><span>                print(key, value)</span></span>
<span class="line"><span>                value:ForceKill(true)</span></span>
<span class="line"><span>            end</span></span>
<span class="line"><span>        end)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>public OnNPCSpawned(event: NpcSpawnedEvent) {</span></span>
<span class="line"><span>    const npc = EntIndexToHScript(keys.entindex);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (npc.IsRealHero() &amp;&amp; npc.bFirstSpawned == undefined) {</span></span>
<span class="line"><span>        npc.bFirstSpawned = true;</span></span>
<span class="line"><span>        OnHeroInGame(npc);</span></span>
<span class="line"><span>    } else if (npc.GetUnitName() == &quot;npc_dota_neutral_kobold&quot;) {</span></span>
<span class="line"><span>        Timers.CreateTimer(() =&gt; {</span></span>
<span class="line"><span>            const units = FindUnitsInRadius(npc.GetTeamNumber(), npc.GetAbsOrigin(), undefined, 500,</span></span>
<span class="line"><span>                                            UnitTargetTeam.ENEMY, UnitTargetType.Basic | UnitTargetType.HERO,</span></span>
<span class="line"><span>                                            UnitTargetFlags.NONE, FindOrder.FIND_ANY_ORDER, false);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            for (const unit of units) {</span></span>
<span class="line"><span>                unit.ForceKill(true);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        });</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div></div></div><p>And the result in-game:</p>`,21)),e(a,{path:h}),n[2]||(n[2]=s('<h2 id="scripting-examples-and-sources" tabindex="-1">Scripting Examples and Sources <a class="header-anchor" href="#scripting-examples-and-sources" aria-label="Permalink to &quot;Scripting Examples and Sources&quot;">​</a></h2><p>There are plenty of examples spread all across GitHub and with the contents of this guide you should now be able to understand the scripting flow of game logic and scripted abilities. The best GitHub repo to look for Dota 2 spells is <a href="https://github.com/Elfansoer/dota-2-lua-abilities" target="_blank" rel="noreferrer">Elfansoer&#39;s dota 2 abilities library</a>. Если вы хотите проверить скрипты определенной игры на <a href="https://steamcommunity.com/workshop/browse/?appid=570&amp;browsesort=trend&amp;section=readytouseitems" target="_blank" rel="noreferrer">Custom Games Workshop</a>, которые не опубликовали свой исходный код на GitHub (потому что они дураки), просто выполните следующие действия:</p><ol><li>Подпишитесь на игру. Загрузите <a href="https://s2v.app/" target="_blank" rel="noreferrer">Source 2 Viewer</a>, если вы еще этого не сделали.</li><li>Откройте Проводник в приложении.</li><li>Откройте мастерскую впк.</li></ol><p>Вручную:</p><ol><li>Проверьте URL-адрес, steamcommunity.com/sharedfiles/filedetails/?id=<strong>скопируйте этот номер</strong>.</li><li>Заходим в папку Steam -&gt; SteamApps -&gt; мастерская -&gt; контент -&gt; 570 (это папка dota)</li><li>Найдите папку со скопированным номером.</li><li>Откройте файл <code>.vpk</code> с помощью GCFScape или S2V и извлеките его содержимое куда угодно. Теперь вы можете получить доступ к его скриптам и скомпилированным моделям/частицам/звукам.</li></ol><p><img src="'+g+'" alt="img"></p><p>Всякий раз, когда у вас возникают сомнения по поводу того, как использовать ту или иную функцию GameAPI, можно найти примеры по всему GitHub, просто написав ее имя, дополнительно отфильтровав по lua, например:</p><p><img src="'+v+'" alt="img"></p><p>Просто убедитесь, что это действительно Dota Lua, а не другой игровой API, поскольку некоторые функции могут иметь одинаковые имена с другими движками.</p><p>Это всё, что касается основ написания скриптов. Если у вас возникнут дополнительные вопросы, <a href="https://t.me/+4wTdvuzBPzUxOTgy" target="_blank" rel="noreferrer">Telegram-канал</a> сообщества доступен круглосуточно.</p>',10))])}const S=p(A,[["render",f]]);export{E as __pageData,S as default};
